/* @lc app=leetcode id=3473 lang=kotlin */ class Solution { fun maxSum(nums: IntArray, k: Int, m: Int): Int = nums.runningFold(0) { a, b -> a + b }.let { pre -> (1..k).fold(IntArray(nums.size + 1)) { prev, j -> IntArray(nums.size + 1) { -1_000_000_000 }.also { cur -> (1..nums.size).fold(-1_000_000_000) { best, i -> maxOf(best, if (i - m >= 0) prev[i - m] - pre[i - m] else -1_000_000_000).also { b -> cur[i] = maxOf(cur[i - 1], if (b > -500_000_000) b + pre[i] else -1_000_000_000) } } } }.last() } }